const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const chongqingPoint = ee.Geometry.Point(106.55, 29.56);
  // Define a small rectangular region around Chongqing city center
  const geometry = chongqingPoint.buffer(20000).bounds(); // 20km buffer

  const startDateFeb = '2020-02-10';
  const endDateFeb = '2020-02-25'; // 16 days

  const startDateApr = '2020-04-20';
  const endDateApr = '2020-05-12'; // 23 days

  const NO2_BAND = 'tropospheric_NO2_column_number_density';
  const SCALE = 1000; // Use a reasonable scale for reduceRegion

  // Function to get mean NO2 and validate collection/pixels
  const getMeanNO2 = async (startDate, endDate, periodName) => {
    let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .select(NO2_BAND)
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.gt('qa_value', 0.75)); // Filter for good quality data

    const collectionSize = await collection.size().getInfo();

    if (collectionSize === 0) {
      console.log(`${periodName} Images: 0`);
      return { value: null, pixels: 0, status: 'C1' };
    }

    const meanImage = collection.mean().clip(geometry);

    // Calculate valid pixels
    const pixelCountDict = await meanImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: SCALE,
      maxPixels: 1e9
    }).getInfo();
    const pixelCount = pixelCountDict[NO2_BAND] || 0;

    if (pixelCount === 0) {
      console.log(`${periodName} Images: ${collectionSize} (Val: 0.0)`);
      return { value: null, pixels: 0, status: 'C2' };
    }

    // Calculate mean NO2
    const meanNO2Dict = await meanImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: SCALE,
      maxPixels: 1e9
    }).getInfo();
    const meanNO2 = meanNO2Dict[NO2_BAND];

    console.log(`${periodName} Images: ${collectionSize} (Val: ${meanNO2 !== null && meanNO2 !== undefined ? meanNO2.toFixed(4) : 'N/A'}), Pixels: ${pixelCount}`);

    if (meanNO2 === null || meanNO2 === undefined || isNaN(meanNO2)) {
      return { value: null, pixels: pixelCount, status: 'C3' };
    }

    return { value: meanNO2, pixels: pixelCount, status: 'OK' };
  };

  // 2. Data Acquisition & Processing for February period
  const febResult = await getMeanNO2(startDateFeb, endDateFeb, "Feb 10-25, 2020");
  if (febResult.status !== 'OK') {
    console.log(febResult.status);
    return;
  }

  // 3. Data Acquisition & Processing for April/May period
  const aprResult = await getMeanNO2(startDateApr, endDateApr, "Apr 20-May 12, 2020");
  if (aprResult.status !== 'OK') {
    console.log(aprResult.status);
    return;
  }

  // 4. Comparison and Final Answer
  const meanNO2Feb = febResult.value;
  const meanNO2Apr = aprResult.value;

  if (meanNO2Feb === null || meanNO2Apr === null) {
      // This case should be handled by the C3 check within getMeanNO2,
      // but as a final safeguard.
      console.log("C3");
      return;
  }

  if (meanNO2Apr > meanNO2Feb) {
    console.log("A"); // NO2 increased
  } else {
    console.log("B"); // NO2 did not increase
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
